/**
 * underground-json-builder.ts - Loads procedurally generated underground rooms from JSON
 *
 * This builder loads the 561 underground rooms (z=-2 through z=-6) from the
 * generated JSON file and creates them in the game world. These rooms were
 * procedurally generated with AI descriptions and connect to building basements
 * at z=-1 via coordinate adjacency.
 *
 * The JSON was generated by scripts/generate-room-descriptions.ts and cleaned
 * by scripts/fix-room-descriptions.ts.
 *
 * Z-level architecture:
 *   z=0: Surface (streets, buildings) - from world-builder.ts
 *   z=-1: Building basements - from building-builder.ts
 *   z=-2: Upper tunnels (326 rooms) - from this builder
 *   z=-3: Transitional passages (145 rooms) - from this builder
 *   z=-4: Lower passages (51 rooms) - from this builder
 *   z=-5: Deep vaults (29 rooms) - from this builder
 *   z=-6: Ancient depths (10 rooms) - from this builder
 */

import * as fs from 'node:fs';
import * as path from 'node:path';
import type { RuntimeObject } from '../../../types/object';
import type { ObjectManager } from '../object-manager';
import { type Builder, registerBuilder } from './builder-registry';

interface GeneratedRoom {
  id: string;
  pos: { x: number; y: number; z: number };
  roomType: string;
  topology: string;
  era: string;
  condition: string;
  atmosphere: string;
  exits: Record<string, boolean>;
  exitCount: number;
  depth: number;
  features: string[];
  nearWater: boolean;
  nearSurface: boolean;
  isDeep: boolean;
  neighborTypes: string[];
  description: string;
  imageOnDisk?: string; // Filename in assets/images/ to load into GridFS
}

interface UndergroundData {
  rooms: GeneratedRoom[];
  meta: {
    generated: string;
    roomCount: number;
  };
}

/**
 * Builds underground rooms from the generated JSON file.
 * Runs after world-builder and building-builder so it can connect
 * to existing rooms via coordinate adjacency.
 */
// Sister Gray's domain coordinates (z=-4 through z=-6)
// Exits INTO these coordinates should be guarded
const SISTER_GRAY_COORDS = new Set([
  // z=-4 key entry points
  '-14,5,-4',   // LJ - Lower Junction (main entry)
  '-14,-5,-4',  // SH - Supply Hub
  '-16,5,-4',   // ARMORY
  '-14,6,-4',   // CB - Cutter Barracks
  '-12,6,-4',   // MEDICAL_BAY
  '-11,5,-4',   // COMMS_CENTER
  '-16,1,-4',   // SW - Spark Workshop
  // z=-5 sensitive areas
  '-14,-5,-5',  // TD - The Descent
  '-14,-3,-5',  // WR - War Room
  '-14,-1,-5',  // TV - The Vault
  '-16,-1,-5',  // CC - Council Chambers
  '-14,1,-5',   // SQ - Sister's Quarters
  '-16,1,-5',   // CL - Clone Lab
  '-16,-3,-5',  // AR - Archive
  '-10,-3,-5',  // HC - Holding Cells
  // z=-6 The Blind
  '-14,1,-6',   // TB - The Blind
]);

export class UndergroundJsonBuilder implements Builder {
  static provides = ['undergroundRooms'];
  static depends = ['room', 'exit', 'guardedExit', 'recycler', 'spatial', 'startRoom', 'buildings', 'basements']; // After world & buildings

  private rooms: Map<string, RuntimeObject> = new Map();
  private roomDefs: Map<string, GeneratedRoom> = new Map(); // JSON definitions for exit flags

  constructor(private manager: ObjectManager) {}

  async build(): Promise<void> {
    const $ = this.manager as any;

    // Check if already built (look for a room with underground:true flag from JSON)
    const testRoom = await $.spatial?.getRoomDataAt(-15, 4, -2);
    if (testRoom && testRoom.get('underground') === true) {
      console.log('  ✅ Underground JSON rooms already loaded');
      return;
    }

    if (!$.room || !$.exit || !$.recycler || !$.spatial) {
      throw new Error(
        'Room, Exit, Recycler, and Spatial must exist before loading underground',
      );
    }

    console.log('  🕳️  Loading generated underground rooms...');

    // Load the JSON file
    const jsonPath = path.join(
      process.cwd(),
      'underground-world-fresh-described-fixed.json',
    );

    if (!fs.existsSync(jsonPath)) {
      console.log('    ⚠️ Underground JSON not found, skipping');
      return;
    }

    const data: UndergroundData = JSON.parse(fs.readFileSync(jsonPath, 'utf-8'));
    console.log(`    Loaded ${data.rooms.length} room definitions from JSON`);

    // Create room objects
    await this.createRooms(data.rooms);
    console.log(`    Created ${this.rooms.size} underground rooms`);

    // Rebuild spatial index BEFORE connecting rooms so we can find building basements
    // (rooms created via $recycler.create auto-register, but basements were created earlier)
    await $.spatial.rebuild();
    console.log('    Rebuilt spatial index for basement connections');

    // Connect rooms with exits (within underground and to building basements)
    await this.connectRooms();

    console.log('  ✅ Underground JSON rooms loaded');
  }

  async registerAliases(): Promise<void> {
    // No global aliases needed - rooms are accessed via coordinates
  }

  /**
   * Create room objects from JSON data
   */
  private async createRooms(rooms: GeneratedRoom[]): Promise<void> {
    const $ = this.manager as any;
    const recycler = $.recycler;
    const roomProto = $.room;

    for (const roomDef of rooms) {
      const { x, y, z } = roomDef.pos;
      const key = this.coordKey(x, y, z);

      // Store JSON definition for exit flag lookup
      this.roomDefs.set(key, roomDef);

      // Check if room already exists at this coordinate
      const existing = await $.spatial?.getRoomDataAt(x, y, z);
      if (existing) {
        // Room already exists (from building-builder), store reference
        this.rooms.set(key, existing);
        continue;
      }

      // Generate a name based on era and room type
      const name = this.generateRoomName(roomDef);

      // Create the room
      const room = await recycler.create({
        parent: roomProto,
        properties: {
          name,
          description: roomDef.description,
          x,
          y,
          z,
          outdoor: false,
          // Store metadata for future reference
          underground: true,
          undergroundEra: roomDef.era,
          undergroundTopology: roomDef.topology,
          undergroundCondition: roomDef.condition,
        },
      });

      // Load image from disk if specified
      if (roomDef.imageOnDisk && $.blob) {
        try {
          const imagePath = path.join(
            process.cwd(),
            'assets/images',
            roomDef.imageOnDisk,
          );
          if (fs.existsSync(imagePath)) {
            const imageData = fs.readFileSync(imagePath);
            const base64Data = imageData.toString('base64');
            const blobKey = await $.blob.write(base64Data, {
              contentType: 'image/png',
              filename: roomDef.imageOnDisk,
              createdBy: 'underground-json-builder',
            });
            // Store by aspect ratio (default 16:9 for rooms)
            room.set('images', { '16:9': blobKey });
          }
        } catch (err) {
          console.warn(`    Warning: Failed to load image ${roomDef.imageOnDisk}: ${err}`);
        }
      }

      this.rooms.set(key, room);
    }
  }

  /**
   * Generate a room name based on era and type
   */
  private generateRoomName(room: GeneratedRoom): string {
    const eraNames: Record<string, string> = {
      victorian: 'Victorian',
      modern: 'Modern',
      depression: 'Depression-Era',
      industrial: 'Industrial',
      deep: 'Deep',
      ancient: 'Ancient',
    };

    const typeNames: Record<string, string> = {
      corridor: 'Passage',
      junction: 'Junction',
      hub: 'Chamber',
      dead_end: 'Alcove',
      entrance: 'Entry Point',
      chamber: 'Chamber',
      shaft: 'Shaft',
      tunnel: 'Tunnel',
    };

    const era = eraNames[room.era] || room.era;
    const type = typeNames[room.roomType] || room.roomType || 'Passage';

    return `${era} ${type}`;
  }

  /**
   * Connect rooms with exits based on adjacency
   */
  private async connectRooms(): Promise<void> {
    const $ = this.manager as any;
    const recycler = $.recycler;
    const exitProto = $.exit;
    const guardedExitProto = $.guardedExit;

    let exitCount = 0;
    let connectedToBuildings = 0;
    let guardedCount = 0;

    const directions = [
      { dx: 0, dy: 1, dz: 0, name: 'north', aliases: ['n'] },
      { dx: 0, dy: -1, dz: 0, name: 'south', aliases: ['s'] },
      { dx: 1, dy: 0, dz: 0, name: 'east', aliases: ['e'] },
      { dx: -1, dy: 0, dz: 0, name: 'west', aliases: ['w'] },
      { dx: 0, dy: 0, dz: 1, name: 'up', aliases: ['u'] },
      { dx: 0, dy: 0, dz: -1, name: 'down', aliases: ['d', 'dn'] },
    ];

    let skippedByJson = 0;

    for (const [key, room] of this.rooms) {
      const [x, y, z] = this.parseKey(key);
      const roomDef = this.roomDefs.get(key);

      for (const dir of directions) {
        // Check JSON exit flags - honor explicit walls/blocked exits
        // If JSON says exit is false for this direction, don't create it
        if (roomDef?.exits && roomDef.exits[dir.name] === false) {
          skippedByJson++;
          continue;
        }

        const nx = x + dir.dx;
        const ny = y + dir.dy;
        const nz = z + dir.dz;
        const neighborKey = this.coordKey(nx, ny, nz);

        // Also check if the neighbor's JSON says the reverse exit is blocked
        const neighborDef = this.roomDefs.get(neighborKey);
        const reverseDir = this.getOppositeDirection(dir.name);
        if (neighborDef?.exits && neighborDef.exits[reverseDir.name] === false) {
          skippedByJson++;
          continue;
        }

        // Check our own rooms first
        let neighbor = this.rooms.get(neighborKey);

        // If not in our rooms, check spatial index (building basements, etc.)
        if (!neighbor) {
          neighbor = await $.spatial?.getRoomDataAt(nx, ny, nz);
          if (neighbor) {
            console.log(`    [SPATIAL] Found room at ${neighborKey}: ${neighbor.get('name')} (#${neighbor.id})`);
          }
        }

        if (neighbor) {
          // Check if exit already exists
          const exits = (room.get('exits') || []) as RuntimeObject[];
          const hasExit = exits.some((e: RuntimeObject) => e.get('name') === dir.name);

          if (!hasExit) {
            // Calculate distance
            const distance = this.calculateDistance(x, y, z, nx, ny, nz);

            // Check if this exit leads INTO Sister Gray's secured domain
            const isGuardedEntry = SISTER_GRAY_COORDS.has(neighborKey);
            const exitParent = isGuardedEntry && guardedExitProto ? guardedExitProto : exitProto;

            // Create exit
            const exitProps: Record<string, unknown> = {
              name: dir.name,
              aliases: dir.aliases,
              destRoom: neighbor,
              distance,
              hidden: false,
              locked: false,
              vehicleAllowed: false, // No vehicles underground
            };

            // Add guard properties for secured entries
            if (isGuardedEntry) {
              exitProps.allowedFaction = 'cartel';
              exitProps.denyMessage = 'The passage ahead is watched. Cartel territory. You are not recognized.';
              guardedCount++;
            }

            const exit = await recycler.create({
              parent: exitParent,
              properties: exitProps,
            });

            await room.call('addExit', exit);
            exitCount++;

            // Track connections to building level
            if (nz === -1 && z === -2) {
              connectedToBuildings++;
            }

            // Create reverse exit if neighbor is a building room (not in our JSON)
            // This ensures bidirectional connectivity
            if (!this.rooms.has(neighborKey)) {
              const reverseDir = this.getOppositeDirection(dir.name);
              const neighborExits = (neighbor.get('exits') || []) as RuntimeObject[];
              const hasReverseExit = neighborExits.some(
                (e: RuntimeObject) => e.get('name') === reverseDir.name
              );

              if (!hasReverseExit) {
                const reverseExit = await recycler.create({
                  parent: exitProto,
                  properties: {
                    name: reverseDir.name,
                    aliases: reverseDir.aliases,
                    destRoom: room,
                    distance,
                    hidden: false,
                    locked: false,
                    vehicleAllowed: false,
                  },
                });
                await neighbor.call('addExit', reverseExit);
                exitCount++;
              }
            }
          }
        }
      }
    }

    console.log(`    Created ${exitCount} underground exits`);
    console.log(`    Honored ${skippedByJson} JSON exit flags (walls/blocked passages)`);
    console.log(`    Connected ${connectedToBuildings} rooms to building basements (z=-1)`);
    console.log(`    Guarded ${guardedCount} entries to Sister Gray's domain`);

    // Log if no connections were made to basements
    if (connectedToBuildings === 0) {
      console.log(`    ⚠️ WARNING: No connections to building basements found!`);
      console.log(`    Checking spatial index for z=-1 rooms...`);
      // Sample check - look for any rooms at z=-1
      const sampleCoords = [
        [-16, 8, -1], [-15, 8, -1], [-15, 9, -1], // City Services
        [2, 3, -1], [1, 3, -1], // Corp Construction
        [9, 3, -1], [9, 2, -1], // Courthouse
      ];
      for (const [sx, sy, sz] of sampleCoords) {
        const sampleRoom = await $.spatial?.getRoomDataAt(sx, sy, sz);
        if (sampleRoom) {
          console.log(`      Found z=-1 room at ${sx},${sy},${sz}: ${sampleRoom.get('name')} (#${sampleRoom.id})`);
        }
      }
    }
  }

  /**
   * Get the opposite direction for bidirectional exits
   */
  private getOppositeDirection(dir: string): { name: string; aliases: string[] } {
    const opposites: Record<string, { name: string; aliases: string[] }> = {
      north: { name: 'south', aliases: ['s'] },
      south: { name: 'north', aliases: ['n'] },
      east: { name: 'west', aliases: ['w'] },
      west: { name: 'east', aliases: ['e'] },
      up: { name: 'down', aliases: ['d', 'dn'] },
      down: { name: 'up', aliases: ['u'] },
    };
    return opposites[dir];
  }

  /**
   * Calculate distance between coordinates (in meters)
   */
  private calculateDistance(
    x1: number,
    y1: number,
    z1: number,
    x2: number,
    y2: number,
    z2: number,
  ): number {
    const dx = (x2 - x1) * 30; // 30m per grid unit horizontal
    const dy = (y2 - y1) * 30;
    const dz = (z2 - z1) * 3; // 3m per floor vertical
    return Math.round(Math.sqrt(dx * dx + dy * dy + dz * dz));
  }

  private coordKey(x: number, y: number, z: number): string {
    return `${x},${y},${z}`;
  }

  private parseKey(key: string): [number, number, number] {
    const [x, y, z] = key.split(',').map(Number);
    return [x, y, z];
  }
}

registerBuilder(UndergroundJsonBuilder);
